// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 seq) public {
        // depositorAccount defaults to address(0), so only address(0) may call
        vm.prank(address(0));
        c.setL1BlockValues(1, 2, 3, bytes32(uint256(4)), seq, bytes32(uint256(6)), 7, 8);

        // General rule: setL1BlockValues never mutates sequenceNumber; it remains 0.
        assertTrue(c.sequenceNumber() == 0);
    }
}
